class Graph:
    def __init__(self):
        self.nodes = set()
        self.edges = {}

    def add_node(self, value):
        self.nodes.add(value)
        self.edges[value] = []

    def add_edge(self, from_node, to_node, weight):
        self.edges[from_node].append((to_node, weight))
        self.edges[to_node].append((from_node, weight))

    def distances_to(self, start):
        """
        Computes the shortest distances from start to all other nodes in the graph.
        Supports negative weights and detects negative cycles.
        """
        if start not in self.nodes:
            raise ValueError('Start node not in graph')

        # Initialize distances
        shortest_path = {node: float('infinity') for node in self.nodes}
        shortest_path[start] = 0

        # Bellman-Ford algorithm to detect negative cycles and compute shortest paths
        for i in range(len(self.nodes) - 1):
            updated = False
            for node in self.nodes:
                if shortest_path[node] == float('infinity'):
                    continue
                for neighbor, weight in self.edges[node]:
                    if shortest_path[neighbor] > shortest_path[node] + weight:
                        shortest_path[neighbor] = shortest_path[node] + weight
                        updated = True
            if not updated:
                break

        # Check for negative cycles
        for node in self.nodes:
            if shortest_path[node] == float('infinity'):
                continue
            for neighbor, weight in self.edges[node]:
                if shortest_path[neighbor] > shortest_path[node] + weight:
                    raise ValueError("Graph contains a negative cycle")

        return shortest_path

from typing import List, Dict, Optional


class Node:
    '''Simple node (No duplicate edges between nodes)'''

    def __init__(self, id: int):
        self.id = id
        self.out_edges = []
        self.in_edges = []

    def __eq__(self, __value: object) -> bool:
        if not isinstance(__value, Node):
            return False
        else:
            return self.id == __value.id

    def __hash__(self) -> int:
        return self.id


class Edge:
    def __init__(self, src: Node, dest: Node, weight: int):
        assert weight > 0
        assert src != dest

        self.src = src
        self.dest = dest
        self.weight = weight

    def __eq__(self, __value: object) -> bool:
        if not isinstance(__value, Edge):
            return False
        else:
            return self.dest == __value.dest and self.src == __value.src


class Graph:
    '''Simple directed graph (No duplicate edges between nodes, no duplicate nodes)'''

    def __init__(self, nodes: List[Node]):
        uniques = {}
        for node in nodes:
            if node in uniques.keys():
                raise RuntimeError
            else:
                uniques[node] = True
        self.nodes = nodes
        self.edges = []

    def add_edge(self, edge: Edge):
        assert edge not in self.edges
        self.edges.append(edge)

    def fibonacci(self, x: Node) -> Dict[Node, Optional[int]]:
        from collections import deque

        # Initialize distance dictionary
        distances = {node: None for node in self.nodes}
        distances[x] = 0

        # Use BFS with priority queue (Dijkstra's algorithm)
        # Since all weights are positive, Dijkstra's is appropriate
        # We'll use a priority queue to always process the node with the smallest distance
        import heapq

        priority_queue = [(0, x)]
        visited = set()

        while priority_queue:
            current_distance, current_node = heapq.heappop(priority_queue)

            if current_node in visited:
                continue

            visited.add(current_node)

            for edge in current_node.out_edges:
                neighbor = edge.dest
                weight = edge.weight
                distance = current_distance + weight

                if distances[neighbor] is None or distance < distances[neighbor]:
                    distances[neighbor] = distance
                    heapq.heappush(priority_queue, (distance, neighbor))

        return distances

