class Sorter:
    def __init__(self):
        pass

    def sort(self, nums: list[int]) -> None:
        if len(nums) <= 1:
            return
        pivot = nums[0]
        left = [x for x in nums[1:] if x <= pivot]
        right = [x for x in nums[1:] if x > pivot]
        self.sort(left)
        self.sort(right)
        nums.clear()
        nums.extend(left)
        nums.append(pivot)
        nums.extend(right)

    def insert(self, nums: list[int], num: int) -> list[int]:
        output = []
        for i, n in enumerate(nums):
            if num < n:
                output.append(num)
                return output + nums[i:]
            else:
                output.append(n)
        return output + [num]

def find_primes(end: int):
    if end < 2:
        return []

    primes = []
    is_prime = [True] * (end + 1)
    is_prime[0] = is_prime[1] = False

    for num in range(2, int(end**0.5) + 1):
        if is_prime[num]:
            primes.append(num)
            for multiple in range(num * num, end + 1, num):
                is_prime[multiple] = False

    for num in range(int(end**0.5) + 1, end + 1):
        if is_prime[num]:
            primes.append(num)

    return primes

def cycle_equality(c1, c2):
    """
    Takes two lists, c1 and c2, and returns True if the two lists represent the same cycle within a permutation group. 
    """
    if len(c1) != len(c2):
        return False
    start_index_b = c2.index(c1[0]) if c1[0] in c2 else -1

    if start_index_b == -1:
        return False
    return c1 == c2[start_index_b:] + c2[:start_index_b]

def permutation_equality(p1, p2):
    """Takes two lists of disjoint cycles that represent two permutation groups, and returns True if they are the same permutation group."""
    if len(p1) != len(p2):
        return False
    hit_count = 0
    for c1 in p1:
        for c2 in p2:
            if cycle_equality(c1, c2):
                hit_count += 1
                break  # Once a match is found, move to next cycle in p1
    return hit_count == len(p1)

class CircularQueue:
    def __init__(self, capacity):
        self.capacity = capacity
        self.queue = [None] * capacity
        self.front = self.rear = -1

    def enqueue(self, item):
        if self.is_full():
            # Queue is full, overwrite the front element
            self.front = (self.front + 1) % self.capacity
        elif self.is_empty():
            # Queue is empty, set front to 0
            self.front = 0
        # Move rear pointer and insert the item
        self.rear = (self.rear + 1) % self.capacity
        self.queue[self.rear] = item

    def dequeue(self):
        if self.is_empty():
            return None
        removed_item = self.queue[self.front]
        if self.front == self.rear:
            self.front = self.rear = -1
        else:
            self.front = (self.front + 1) % self.capacity
        return removed_item

    def peek(self):
        if self.is_empty():
            return None
        return self.queue[self.front]

    def is_empty(self):
        return self.front == -1

    def is_full(self):
        return (self.rear + 1) % self.capacity == self.front

import ast


class UsageCounter(ast.NodeVisitor):
    """
    Counts the usages of each identifier in the given AST.
    An usage does not count the definition or assignment itself;
    only identifiers that are used after their definition/assignment are counted.
    NOTE: This class does not handle the scoping rules of Python;
    it simply counts the usages based on the name of the identifiers.
    It also supports identifiers defined in either a function, assignment operation,
    or function argument definitions.
    """

    def __init__(self):
        self.usages = {}

    def visit_Name(self, node):
        if node.id in self.usages:
            self.usages[node.id] += 1
        self.generic_visit(node)

    def visit_FunctionDef(self, node):
        if node.name not in self.usages:
            self.usages[node.name] = 0
        self.generic_visit(node)

    def visit_Assign(self, node):
        id_defined = None
        for target in node.targets:
            if isinstance(target, ast.Name):
                if target.id not in self.usages:
                    self.usages[target.id] = 0
                id_defined = target.id
            elif isinstance(target, ast.Tuple):
                for elt in target.elts:
                    if isinstance(elt, ast.Name):
                        if elt.id not in self.usages:
                            self.usages[elt.id] = 0
                        id_defined = elt.id
        self.generic_visit(node)
        if id_defined is not None:
            self.usages[id_defined] -= 1

